package ec.edu.unl.sec.selfassessment.api;
import ec.edu.unl.sec.selfassessment.application.*;import jakarta.servlet.http.*;import java.net.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestControllerAdvice(basePackages="ec.edu.unl.sec.selfassessment.api")public class ProcessExceptionHandler{@ExceptionHandler(ProcessProblemException.class)ProblemDetail process(ProcessProblemException e,HttpServletRequest r){HttpStatus s=switch(e.kind()){case UNAUTHORIZED->HttpStatus.UNAUTHORIZED;case FORBIDDEN->HttpStatus.FORBIDDEN;case NOT_FOUND->HttpStatus.NOT_FOUND;case CONFLICT->HttpStatus.CONFLICT;case PRECONDITION->HttpStatus.PRECONDITION_FAILED;case INVALID->HttpStatus.BAD_REQUEST;};var p=ProblemDetail.forStatusAndDetail(s,e.getMessage());p.setType(URI.create("urn:sec-unl:problem:"+e.code().toLowerCase().replace('_','-')));p.setTitle(s.getReasonPhrase());p.setInstance(URI.create(r.getRequestURI()));p.setProperty("code",e.code());p.setProperty("correlationId",String.valueOf(r.getAttribute("sec.correlationId")));p.setProperty("details",java.util.Map.of());return p;}}
